def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        # Check the row index to determine the direction
        if i % 2 == 0:
            # Traverse right on even rows
            for j in range(len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse left on odd rows
            for j in range(len(grid[i]) - 1, -1, -1):
                if (len(grid[i]) - 1 - j) % 2 == 0:
                    result.append(grid[i][j])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            a, b = int(s[i]), int(s[i + 1])
            if count[s[i]] == a and count[s[i + 1]] == b:
                return s[i] + s[i + 1]
    return ""

