def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return n
    # dp[i] will store the length of the longest subsequence that ends with nums[i]
    dp = [1] * n
    max_length = 1

    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) >= (dp[j] - 1) and dp[j] > 1:
                dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])

    return max_length

