def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize the dp array with costs
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    # Fill dp table based on the constraints
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i - 1][(j + 1) % 3],  # Different color from previous
                dp[i - 1][(j + 2) % 3]   # Different color from previous
            )

    # Equidistant condition checks (0 with n-1, 1 with n-2, etc.)
    # We need to ensure symmetry is maintained between houses.
    for i in range(n // 2):
        for j in range(3):
            if (j == 0):  # If we're considering house n-1 painted with color 1 (j == 0)
                dp[n - 1 - i][j] = float('inf')  # Cannot pick this color for equidistant house
            else:
                dp[n - 1 - i][j] = cost[n - 1 - i][j] + min(
                    dp[i][(j + 1) % 3],
                    dp[i][(j + 2) % 3]
                )

    # Return minimum cost for the last house considering all colors
    return min(dp[n - 1])

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    user_offline_timestamps = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        # Process offline users and update their status before any message processing
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= user_offline_timestamps[user_id] + 60:
                online_status[user_id] = True

        if event_type == "OFFLINE":
            user_id = int(args[0])
            online_status[user_id] = False
            user_offline_timestamps[user_id] = timestamp

        elif event_type == "MESSAGE":
            mentions_string = args[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                user_ids = mentions_string.split()
                for user_id in user_ids:
                    user_id = int(user_id[2:])  # Extracting the id from id<number>
                    mentions[user_id] += 1

    return mentions
